// Spike: run the spores-scribe TUI Spore in a Worker.
//
// `spore/` is generated by build.mjs and is not checked in:
//
//   node build.mjs ~/src/fungOS/spores-scribe/spores/tui/module.wasm tui
//   wrangler dev --local --port 8799
import { $init, frame, render, start } from "../spore/tui.js";

const text = (value) => new Response(`${value}\n`);

function size(url) {
  const cols = Number(url.searchParams.get("cols") ?? 80);
  const rows = Number(url.searchParams.get("rows") ?? 24);
  if (!Number.isInteger(cols) || cols < 1 || cols > 500) {
    throw new Error("cols must be an integer from 1 to 500");
  }
  if (!Number.isInteger(rows) || rows < 1 || rows > 500) {
    throw new Error("rows must be an integer from 1 to 500");
  }
  return [cols, rows];
}

export default {
  async fetch(request) {
    await $init;
    const url = new URL(request.url);
    try {
      switch (url.pathname) {
        case "/health":
          return text("ok");
        case "/start": {
          const [cols, rows] = size(url);
          return text(start(cols, rows));
        }
        case "/frame":
          return text(frame());
        case "/render":
        case "/": {
          const [cols, rows] = size(url);
          return text(render(cols, rows, Number(url.searchParams.get("tick") ?? 0)));
        }
        default:
          return new Response("not found\n", { status: 404 });
      }
    } catch (error) {
      return new Response(`spore failed: ${error?.stack ?? error}\n`, {
        status: 500,
      });
    }
  },
};
